import unittest
from candidate import fizz_buzz

class TestFizzBuzz(unittest.TestCase):
    def test_fizz_buzz_small_number(self):
        self.assertEqual(fizz_buzz(10), 0)

    def test_fizz_buzz_larger_number(self):
        self.assertEqual(fizz_buzz(50), 0)

    def test_fizz_buzz_number_with_7(self):
        self.assertEqual(fizz_buzz(78), 2)

    def test_fizz_buzz_number_with_multiple_7(self):
        self.assertEqual(fizz_buzz(79), 3)

    def test_fizz_buzz_number_divisible_by_11(self):
        self.assertEqual(fizz_buzz(33), 0)

    def test_fizz_buzz_number_divisible_by_13(self):
        self.assertEqual(fizz_buzz(39), 0)

    def test_fizz_buzz_number_divisible_by_both(self):
        self.assertEqual(fizz_buzz(143), 1)

    def test_fizz_buzz_zero_input(self):
        self.assertEqual(fizz_buzz(0), 0)

    def test_fizz_buzz_negative_input(self):
        with self.assertRaises(ValueError):
            fizz_buzz(-10)

    def test_fizz_buzz_non_integer_input(self):
        with self.assertRaises(TypeError):
            fizz_buzz(10.5)

    def test_fizz_buzz_none_input(self):
        with self.assertRaises(TypeError):
            fizz_buzz(None)

if __name__ == '__main__':
    unittest.main()
